import sys
from bisect import bisect_left

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    P = [0] * (n + 1)
    for i in range(n):
        P[i + 1] = P[i] + (1 if data[1 + i] == '1' else -1)
    # nxt[l] = first index k > l with P[k] < P[l], or n + 1
    nxt = [n + 1] * (n + 1)
    st = []
    for k in range(n + 1):
        while st and P[st[-1]] > P[k]:
            nxt[st.pop()] = k
        st.append(k)
    pos = {}
    for k in range(n + 1):
        pos.setdefault(P[k], []).append(k)
    best = 0
    for l in range(n + 1):
        lst = pos[P[l]]
        j = bisect_left(lst, nxt[l]) - 1
        if lst[j] - l > best:
            best = lst[j] - l
    print(best)

